        seconds=_parse_seconds(seconds),
    )


def _parse_seconds(text: str | None) -> float:
    if text is None:
        return 0
    if "." in text:
        return float(text)
    return int(text)


def format(duration: Duration) -> str:
    """Write ``duration`` in canonical ISO 8601 form."""
    date = ""
    for value, unit in (
        (duration.years, "Y"),
        (duration.months, "M"),
        (duration.weeks, "W"),
        (duration.days, "D"),
    ):
        date += _format_part(value, unit)
    time = ""
    for value, unit in ((duration.hours, "H"), (duration.minutes, "M")):
        time += _format_part(value, unit)
    seconds = _format_seconds(duration.seconds)
    if seconds != "0":
        time += f"{seconds}S"
    if not date and not time:
        return "PT0S"
    return "P" + date + ("T" + time if time else "")


def _format_part(value: int, unit: str) -> str:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError(f"{unit} part must be a non-negative integer: {value!r}")
    return f"{value}{unit}" if value else ""


def _format_seconds(seconds: float) -> str:
    if isinstance(seconds, bool) or not math.isfinite(seconds) or seconds < 0:
        raise ValueError(f"seconds must be finite and non-negative: {seconds!r}")
    return f"{seconds:.{_SECOND_DECIMALS}f}".rstrip("0").rstrip(".")


def add(moment: datetime, duration: Duration) -> datetime:
    """``moment`` plus ``duration``."""
    month_index = moment.month - 1 + duration.years * 12 + duration.months
    year = moment.year + month_index // 12
    month = month_index % 12 + 1
    if not 1 <= year <= 9999:
        raise ValueError(f"year {year} is out of range")
    day = min(moment.day, calendar.monthrange(year, month)[1])
    moment = moment.replace(year=year, month=month, day=day)
    elapsed = timedelta(
        weeks=duration.weeks,
        days=duration.days,
        hours=duration.hours,
        minutes=duration.minutes,
        seconds=duration.seconds,
    )
    if moment.utcoffset() is None:
        return moment + elapsed
    # Aware datetimes: add in UTC so the result is exact elapsed time even
    # across a UTC offset change, then return to the original time zone.
    return (moment.astimezone(timezone.utc) + elapsed).astimezone(moment.tzinfo)

